        # Implement your hash function here
        return key % self.size

    def separate_chaining(self, key, value):
        index = self.hash_function(key)
        if self.table[index] is None:
            self.table[index] = Node(key, value)
        else:
            node = self.table[index]
            while node is not None:
                if node.key == key:
                    node.value = value
                    return
                node = node.next
            self.table[index] = Node(key, value, self.table[index])

    def delete(self, key):
        index = self.hash_function(key)
        node = self.table[index]
        prev_node = None
        while node is not None:
            if node.key == key:
                if prev_node is None:
                    self.table[index] = node.next
                else:
                    prev_node.next = node.next
                return
            prev_node = node
            node = node.next

    def search(self, key):
        index = self.hash_function(key)
        node = self.table[index]
        while node is not None:
            if node.key == key:
                return node.value
            node = node.next
        return None

    class Node:
        def __init__(self, key, value, next=None):
            self.key = key
            self.value = value
            self.next = next
