```c
#include <stdio.h>

long long fib(int n, int fibMemo[]) {
    if (n <= 0) {
        return 0;
    } else if (n == 1) {
        return 1;
    }

    // check if the result is already computed
    if (fibMemo[n] != -1) {
        return fibMemo[n];
    }

    // compute and store the result
    fibMemo[n] = fib(n - 1, fibMemo) + fib(n - 2, fibMemo);
    return fibMemo[n];
}

int main() {
