    printf("Enter the value of n: ");
    scanf("%d", &n);

    int fibMemo[n + 1];
    for (int i = 0; i <= n; i++) {
        fibMemo[i] = -1;
    }

    long long fibResult = fib(n, fibMemo);
    printf("Fibonacci(%d) = %lld\n", n, fibResult);

    return 0;
}
```

