Here's a simple implementation of a hash table from scratch in Python:

```python
class HashTable:
    def __init__(self):
        self.size = 1000
        self.table = [None] * self.size

    def hash_function(self, key):
        return hash(key) % self.size

    def insert(self, key, value):
        index = self.hash_function(key)
        if self.table[index] is None:
            self.table[index] = (key, value)
        else:
            if self.table[index][0] == key:
                self.table[index][1] = value
            else:
                self.table[index] = (key, value)

    def find(self, key):
        index = self.hash_function(key)
        if self.table[index] is not None and self.table[index][0] == key:
            return self.table[index][1]
        else:
            return None

    def delete(self, key):
        index = self.hash_function(key)
        if self.table[index] is not None and self.table[index][0] == key:
            self.table[index] = None

    def display(self):
        for i in range(self.size):
            if self.table[i] is not None:
                print(f'{i}: {self.table[i]}')

# usage
hash_table = HashTable()
hash_table.insert("test", 1)
hash_table.insert("test2", 2)
print(hash_table.find("test")) # prints 1
hash_table.delete("test")
hash_table.display() # prints only "test2"
```

